#!/usr/bin/env python3
from __future__ import annotations
import argparse, json
from pathlib import Path

PAGE='''<!doctype html><meta charset="utf-8"><title>Rain Badminton Cut review</title>
<style>body{font:15px system-ui;max-width:1100px;margin:24px auto;padding:0 16px;background:#f6f7f9}article,.settings{background:white;padding:14px;margin:12px 0;border-radius:10px}video{width:100%;max-height:420px;background:#111}input[type=number]{width:90px}button{padding:8px 14px;margin:5px}label{margin-right:12px}</style>
<h1>羽毛球回合复核</h1><p id="summary"></p><div class="settings"><strong>01 指定目标与集锦方式</strong><br><label>类型 <select id="mode"><option value="activity">普通活动集锦</option><option value="person">指定人物集锦</option></select></label><label>人物特征 <input id="target" placeholder="例如白衣黄裤"></label><label>回合数量 N <input id="count" type="number" min="1" step="1"></label><button onclick="selectTop()">按评分预选 N 段</button><p>02 按原片顺序复核候选；运动量只能提示活跃范围，请检查发球、结束点及人物。</p></div><p id="status">请逐段复核，再导出交接清单。</p><div id="clips"></div><button onclick="download()">导出 edits.json</button><button onclick="downloadHandoff()">导出 ChatCut 交接清单</button><button onclick="renderHighlights()">确认并生成预览合集</button>
<script>const data=__DATA__;const source=data.source;const preview=data.preview_source||source;const state={source,plan:'standard',output:{resolution:'original',video_bitrate_kbps:null},weights:{},confirmed:false,clips:[]};
document.querySelector('#mode').value=data.initial_mode||'activity';document.querySelector('#target').value=data.target_description||'';
for(const [k,v] of Object.entries(data.candidates[0]?.signals||{}))state.weights[k]=v?1:1;
state.clips=data.candidates.map(x=>({id:x.id,keep:false,start:x.start,end:x.end,target_confirmed:false,highlight:false,note:''}));
const count=document.querySelector('#count');count.max=data.candidates.length;count.value=Math.min(8,data.candidates.length);
document.querySelector('#summary').textContent=`候选 ${data.candidates.length} 段｜原视频 ${data.duration.toFixed(1)} 秒｜请确认时间范围后导出`;
const root=document.querySelector('#clips');data.candidates.forEach((x,i)=>{const a=document.createElement('article');a.innerHTML=`<h3>${x.id}　评分 ${x.score}</h3><p>${x.reasons.join('；')}｜边界可靠性提示 ${x.completeness_confidence}</p><video controls preload="metadata" src="${preview.replaceAll('\\\\','/')}" data-start="${x.start}" data-end="${x.end}"></video><label><input type="checkbox" data-i="${i}" onchange="state.clips[${i}].keep=this.checked"> 保留</label><label><input type="checkbox" onchange="state.clips[${i}].target_confirmed=this.checked"> 已确认指定人物有精彩表现</label><label><input type="checkbox" onchange="state.clips[${i}].highlight=this.checked"> 高光</label> 起 <input type="number" min="0" max="${data.duration}" step="0.01" value="${x.start}" data-s="${i}"> 止 <input type="number" min="0" max="${data.duration}" step="0.01" value="${x.end}" data-e="${i}"> <label>备注 <input type="text" maxlength="200" onchange="state.clips[${i}].note=this.value"></label>`;const v=a.querySelector('video');v.addEventListener('loadedmetadata',()=>{v.currentTime=Number(v.dataset.start)});v.addEventListener('timeupdate',()=>{if(v.currentTime>=state.clips[i].end)v.pause()});root.append(a)});
document.addEventListener('change',e=>{if(e.target.dataset.s)state.clips[e.target.dataset.s].start=Number(e.target.value);if(e.target.dataset.e)state.clips[e.target.dataset.e].end=Number(e.target.value)});
function selectTop(){const n=Number(count.value);if(!Number.isInteger(n)||n<1||n>state.clips.length){document.querySelector('#status').textContent='请填写有效的回合数量';return}const ranked=data.candidates.map((c,i)=>({i,score:c.score})).sort((a,b)=>b.score-a.score).slice(0,n),chosen=new Set(ranked.map(x=>x.i));state.clips.forEach((c,i)=>{c.keep=chosen.has(i);root.querySelector(`[data-i="${i}"]`).checked=c.keep});document.querySelector('#status').textContent=`已预选 ${n} 段，请逐段复核`}
function confirmed(){const n=Number(count.value),selected=state.clips.filter(c=>c.keep).sort((a,b)=>a.start-b.start),mode=document.querySelector('#mode').value,target=document.querySelector('#target').value.trim();if(!Number.isInteger(n)||n<1||n>state.clips.length||selected.length!==n)throw Error(`请恰好保留 ${n} 段`);if(selected.some(c=>!Number.isFinite(c.start)||!Number.isFinite(c.end)||c.start<0||c.end>data.duration||c.start>=c.end))throw Error('片段时间必须位于原片内，且结束晚于开始');if(selected.some((c,i)=>i>0&&c.start<selected[i-1].end))throw Error('保留片段之间不能重叠');if(mode==='person'&&(!target||selected.some(c=>!c.target_confirmed)))throw Error('指定人物集锦须填写人物特征，并逐段确认其精彩表现');return {...state,confirmed:true,target_count:n,mode,target_description:target}}
function download(){try{const b=new Blob([JSON.stringify(confirmed(),null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='edits.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(error){document.querySelector('#status').textContent=error.message}}
function downloadHandoff(){try{const edits=confirmed(),selected=edits.clips.filter(c=>c.keep).sort((a,b)=>a.start-b.start);const handoff={schema_version:1,sport:'badminton',target_description:edits.target_description,mode:edits.mode,sources:[{id:'source-1',name:source.split('/').pop(),path:source}],segments:selected.map(c=>({id:c.id,source_id:'source-1',start_s:c.start,end_s:c.end,segment_kind:'rally',highlight:!!c.highlight,identity_status:edits.mode==='person'?'confirmed_target':'uncertain',note:c.note||''}))};const b=new Blob([JSON.stringify(handoff,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='badminton-chatcut-handoff.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}catch(error){document.querySelector('#status').textContent=error.message}}
async function renderHighlights(){const status=document.querySelector('#status');try{const edits=confirmed();status.textContent='正在生成合集…';const r=await fetch('/render',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(edits)}),body=await r.json();if(!r.ok)throw new Error(body.error||'渲染失败');status.textContent=`完成：${body.output}`}catch(error){status.textContent=`无法直接渲染：${error.message}。若此页面是直接打开的，请先导出 edits.json，再运行 render_highlights.py。`}}</script>'''

def main():
 ap=argparse.ArgumentParser();ap.add_argument('clips',type=Path);ap.add_argument('--out',type=Path,default=Path('review.html'));ap.add_argument('--video-src');ap.add_argument('--mode',choices=('activity','person'),default='activity');ap.add_argument('--target-description',default='');a=ap.parse_args();data=json.loads(a.clips.read_text(encoding='utf-8'))
 if a.video_src: data['preview_source']=a.video_src
 data['initial_mode']=a.mode;data['target_description']=a.target_description
 a.out.write_text(PAGE.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('</','<\\/')),encoding='utf-8');print(f'Wrote {a.out}')
if __name__=='__main__':main()
